code='''from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[r[:] for r in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==0 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        for y,x in q:
          comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            z=(y+dy,x+dx)
            if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]]!=0 and z not in seen:
              seen.add(z); q.append(z)
        y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
        layers={}
        for y,x in comp:
          d=min(y-y0,y1-y,x-x0,x1-x)
          layers.setdefault(d,grid[y][x])
        depths=sorted(layers)
        cmap={layers[d]:layers[depths[-1-i]] for i,d in enumerate(depths)}
        for y,x in comp: out[y][x]=cmap[grid[y][x]]
    return out
'''
